// Item catalogue: equipment (generated by tier), consumables, upgrade scrolls, and monster drops.
// Every equip has 7 upgrade slots. Drops roll a little stat variance; shop items don't.

export const EQUIP_SLOTS = ['weapon', 'hat', 'top', 'bottom', 'shoes', 'gloves', 'cape', 'earring'];
export const UPGRADE_SLOTS = 7;

export const ITEMS = {};

function add(def) {
  ITEMS[def.id] = def;
  return def;
}

// ---------- Weapons ----------

const WEAPON_TIERS = [
  { level: 0, prefix: 'Wooden', color: '#c99a6b' },
  { level: 10, prefix: 'Copper', color: '#e08a4f' },
  { level: 15, prefix: 'Iron', color: '#a8b0bd' },
  { level: 20, prefix: 'Steel', color: '#cfd8e6' },
  { level: 25, prefix: 'Silver', color: '#eef3ff' },
  { level: 30, prefix: 'Crystal', color: '#8fe3ff' },
  { level: 35, prefix: 'Starlit', color: '#ffe36b' },
  { level: 40, prefix: 'Royal', color: '#ff9ec0' },
  { level: 50, prefix: 'Celestial', color: '#c9a6ff' },
];

const BASE_WATK = [14, 25, 32, 40, 48, 56, 65, 75, 88];
const BASE_MATK = [8, 15, 22, 30, 38, 46, 55, 64, 76];

// `scale` evens out damage between weapon types; `family` limits who can equip tiers above Wooden.
const WEAPON_KINDS = {
  sword: { label: 'Sword', family: 'warrior', scale: 1.0, magic: false },
  axe: { label: 'Axe', family: 'warrior', scale: 0.95, magic: false },
  spear: { label: 'Spear', family: 'warrior', scale: 0.85, magic: false },
  wand: { label: 'Wand', family: 'mage', scale: 0.5, magic: true },
  staff: { label: 'Staff', family: 'mage', scale: 0.55, magic: true, matkBonus: 1.12 },
  bow: { label: 'Bow', family: 'archer', scale: 0.8, magic: false },
  crossbow: { label: 'Crossbow', family: 'archer', scale: 0.78, magic: false },
  dagger: { label: 'Dagger', family: 'thief', scale: 0.98, magic: false },
  claw: { label: 'Claw', family: 'thief', scale: 0.75, magic: false },
};

for (const [type, kind] of Object.entries(WEAPON_KINDS)) {
  WEAPON_TIERS.forEach((tier, t) => {
    const stats = { watk: Math.round(BASE_WATK[t] * kind.scale) };
    if (kind.magic) stats.matk = Math.round(BASE_MATK[t] * (kind.matkBonus ?? 1));
    add({
      id: `${type}_${t}`,
      name: `${tier.prefix} ${kind.label}`,
      type: 'equip',
      slot: 'weapon',
      weaponType: type,
      tier: t,
      reqLevel: tier.level,
      family: t === 0 ? null : kind.family,
      stats,
      price: Math.round(100 + 120 * t * t + 400 * t),
      color: tier.color,
    });
  });
}

// ---------- Armor ----------

const ARMOR_TIERS = [
  { level: 0, prefix: 'Cotton', color: '#ffc2d6' },
  { level: 10, prefix: 'Linen', color: '#a8dcff' },
  { level: 20, prefix: 'Leather', color: '#ffb38a' },
  { level: 30, prefix: 'Silver', color: '#c9d6ff' },
  { level: 40, prefix: 'Starlit', color: '#ffe98a' },
  { level: 50, prefix: 'Celestial', color: '#d2b8ff' },
];

const ARMOR_KINDS = {
  hat: { label: 'Cap', def: (t) => 3 + t * 6, extra: (t) => ({ hp: t * 10 }) },
  top: { label: 'Tunic', def: (t) => 5 + t * 8, extra: () => ({}) },
  bottom: { label: 'Trousers', def: (t) => 3 + t * 6, extra: () => ({}) },
  shoes: { label: 'Boots', def: (t) => 2 + t * 3, extra: (t) => ({ speed: t >= 2 ? 2 + t : 0 }) },
  gloves: { label: 'Gloves', def: (t) => 2 + t * 3, extra: (t) => ({ watk: t >= 2 ? t - 1 : 0, acc: 1 + t }) },
  cape: { label: 'Cape', def: (t) => 2 + t * 4, extra: (t) => ({ mdef: 2 + t * 4, eva: t }) },
  earring: { label: 'Earrings', def: () => 0, extra: (t) => ({ matk: 1 + t * 2, mp: 10 + t * 15 }) },
};

for (const [slot, kind] of Object.entries(ARMOR_KINDS)) {
  ARMOR_TIERS.forEach((tier, t) => {
    const stats = { wdef: kind.def(t), ...kind.extra(t) };
    for (const k of Object.keys(stats)) if (!stats[k]) delete stats[k];
    add({
      id: `${slot}_${t}`,
      name: `${tier.prefix} ${kind.label}`,
      type: 'equip',
      slot,
      tier: t,
      reqLevel: tier.level,
      family: null,
      stats,
      price: Math.round(60 + 90 * t * t + 250 * t),
      color: tier.color,
    });
  });
}

// ---------- Consumables ----------

add({ id: 'red_potion', name: 'Strawberry Tonic', type: 'use', price: 50, effect: { hp: 50 }, color: '#ff6b8a', desc: 'Restores 50 HP.' });
add({ id: 'orange_potion', name: 'Peach Tonic', type: 'use', price: 160, effect: { hp: 150 }, color: '#ffa94d', desc: 'Restores 150 HP.' });
add({ id: 'white_potion', name: 'Milk Tonic', type: 'use', price: 320, effect: { hp: 300 }, color: '#fff7ea', desc: 'Restores 300 HP.' });
add({ id: 'blue_potion', name: 'Blueberry Tonic', type: 'use', price: 200, effect: { mp: 100 }, color: '#6fb8ff', desc: 'Restores 100 MP.' });
add({ id: 'mana_elixir', name: 'Moonberry Tonic', type: 'use', price: 620, effect: { mp: 300 }, color: '#a58cff', desc: 'Restores 300 MP.' });
add({ id: 'elixir', name: 'Rainbow Elixir', type: 'use', price: 3000, effect: { hpPct: 0.5, mpPct: 0.5 }, color: '#ffd66b', desc: 'Restores half your HP and MP.' });
add({ id: 'return_scroll', name: 'Homeward Scroll', type: 'use', price: 400, effect: { returnTown: true }, color: '#bff0dc', desc: 'Takes you back to the nearest town.' });

// ---------- Upgrade scrolls ----------
// Each use spends one upgrade slot, pass or fail.

const ARMOR_SLOTS = ['hat', 'top', 'bottom', 'shoes', 'cape'];

const SCROLLS = [
  { id: 'scroll_watk_100', name: 'Weapon Charm: ATK 100%', slots: ['weapon'], chance: 1.0, stats: { watk: 1 }, price: 2500 },
  { id: 'scroll_watk_60', name: 'Weapon Charm: ATK 60%', slots: ['weapon'], chance: 0.6, stats: { watk: 2 } },
  { id: 'scroll_watk_10', name: 'Weapon Charm: ATK 10%', slots: ['weapon'], chance: 0.1, stats: { watk: 5, str: 1 } },
  { id: 'scroll_matk_60', name: 'Weapon Charm: Magic 60%', slots: ['weapon'], chance: 0.6, stats: { matk: 2 } },
  { id: 'scroll_matk_10', name: 'Weapon Charm: Magic 10%', slots: ['weapon'], chance: 0.1, stats: { matk: 5, int: 1 } },
  { id: 'scroll_def_100', name: 'Armor Charm: DEF 100%', slots: ARMOR_SLOTS, chance: 1.0, stats: { wdef: 1 }, price: 1500 },
  { id: 'scroll_def_60', name: 'Armor Charm: DEF 60%', slots: ARMOR_SLOTS, chance: 0.6, stats: { wdef: 2, hp: 10 } },
  { id: 'scroll_def_10', name: 'Armor Charm: DEF 10%', slots: ARMOR_SLOTS, chance: 0.1, stats: { wdef: 5, hp: 30 } },
  { id: 'scroll_glove_60', name: 'Glove Charm: ATK 60%', slots: ['gloves'], chance: 0.6, stats: { watk: 1 } },
  { id: 'scroll_glove_10', name: 'Glove Charm: ATK 10%', slots: ['gloves'], chance: 0.1, stats: { watk: 3 } },
  { id: 'scroll_luck_60', name: 'Trinket Charm: All Stats 60%', slots: ['earring', 'cape'], chance: 0.6, stats: { str: 1, dex: 1, int: 1, luk: 1 } },
];

for (const s of SCROLLS) {
  add({
    id: s.id,
    name: s.name,
    type: 'use',
    price: s.price ?? 0,
    scroll: { slots: s.slots, chance: s.chance, stats: s.stats },
    color: s.chance >= 1 ? '#bff0dc' : s.chance >= 0.6 ? '#8fd3ff' : '#ff9ec0',
    desc: `Use on ${s.slots.join('/')}. ${Math.round(s.chance * 100)}% success.`,
  });
}

